// event-invite/strings.js - UI strings of Event Invite (designer and guests pages) in the 7 UI languages, plus the
// texts the invitation itself needs: 'ei.inv.*' (collected into every exported page for its content languages),
// 'ei.sc.*' (scenario texts of the event types) and 'ei.pg.*' (programme items).
//
// Structure: one flat object per language (en, ru, uk, de, fr, es, ka), keys namespaced by area: ei.c.* card
// titles, ei.f.* fields, ei.g.* guests page, ei.s.* summary, ei.st.* RSVP statuses, ei.x.* exports, ei.sv.* server,
// ei.r.* reply options, ei.d.* / ei.theme.* / ei.orn.* / ei.font.* design. Flat keys (not nested objects) so grep
// finds every use, and a missing key falls back per key (to English, then to a humanised key in ui/i18n.js).
// Placeholders are {name}; plural values are objects keyed by Intl.PluralRules categories (one / few / many / other).
// English is the reference: every other dictionary should hold the same keys.
// Imported for its side effect only (common.js imports it first), so registration precedes any t() call.
import { addDicts } from '../ui/i18n.js';

